<?php $title='Payment';require __DIR__.'/../includes/header.php';require_login('customer');require __DIR__.'/../config/database.php';$id=(int)($_GET['request']??0);$st=$pdo->prepare("SELECT r.*,c.name category,c.access_fee,pr.name province,d.name district,ci.name city,v.brand,v.model,v.vehicle_type,v.registration_number,v.transmission FROM assistance_requests r JOIN service_categories c ON c.id=r.category_id LEFT JOIN provinces pr ON pr.id=r.province_id LEFT JOIN districts d ON d.id=r.district_id LEFT JOIN cities ci ON ci.id=r.city_id LEFT JOIN vehicles v ON v.id=r.vehicle_id WHERE r.id=? AND r.customer_id=?");$st->execute([$id,$_SESSION['user_id']]);$r=$st->fetch();if(!$r)redirect(BASE_URL.'customer/dashboard.php'); ?>
<section class="section-pad"><div class="container"><div class="infinex-stepper mb-4"><span class="done"><b><i class="bi bi-check"></i></b> Vehicle details</span><i class="bi bi-chevron-right"></i><span class="done"><b><i class="bi bi-check"></i></b> Service</span><i class="bi bi-chevron-right"></i><span class="done"><b><i class="bi bi-check"></i></b> Location</span><i class="bi bi-chevron-right"></i><span class="active"><b>4</b> Payment</span></div><div class="row justify-content-center"><div class="col-lg-7"><div class="card border-0 shadow-sm rounded-4 p-4"><span class="text-warning fw-bold">STEP 4</span><h1 class="fw-bold">Unlock provider details</h1><div class="vehicle-summary-strip mb-3"><i class="bi bi-car-front-fill"></i><div><strong><?=e($r['brand'].' '.$r['model'])?></strong><small><?=e($r['registration_number'])?> · <?=e($r['vehicle_type'])?> · <?=e($r['transmission'])?></small></div></div><p class="text-muted">Breakdown location:<br><strong><?=e($r['address']??'Exact location provided')?></strong><br><small class="text-muted">Coordinates captured: <?=($r['latitude']!==null&&$r['longitude']!==null)?'Yes':'No'?></small></p><div class="bg-light rounded-3 p-4 my-3"><div class="d-flex justify-content-between"><span>INFINEX platform access fee</span><strong>Rs. <?=number_format($r['access_fee'],2)?></strong></div></div><div class="alert alert-info small">This payment is only for access to suitable provider information. Repair/service charges are paid separately to the provider.</div><form action="payment-process.php" method="post"><input type="hidden" name="request_id" value="<?=$id?>"><button class="btn btn-warning btn-lg w-100 fw-bold">Pay Rs. <?=number_format($r['access_fee'],0)?> & Unlock</button></form><p class="small text-muted mt-3 mb-0">Demo mode: this button simulates a successful gateway response. Replace it with your selected Sri Lankan payment gateway before production.</p></div></div></div></div></section><?php require __DIR__.'/../includes/footer.php'; ?>